styles.content:
.wf-help-desk {
    --hd-surface: var(--wf-color-surface, light-dark(#fff, #17253a));
    --hd-raised: var(--wf-color-background, light-dark(#f3f6fa, #102035));
    --hd-text: var(--wf-color-text, light-dark(#15253a, #e5edf8));
    --hd-muted: var(--wf-color-muted, light-dark(#4e6075, #b3c3d7));
    --hd-line: var(--wf-color-border, light-dark(#d6dde6, #40516a));
    --hd-focus: var(--wf-color-primary, light-dark(#1d5999, #9dcaff));
    box-sizing: border-box;
    width: min(100%, 1180px);
    padding: clamp(16px, 4vw, 44px);
    margin-inline: auto;
    color: var(--hd-text);
}
.wf-help-desk *, .wf-help-desk *::before, .wf-help-desk *::after { box-sizing: border-box; }
.wf-help-desk [hidden] { display: none !important; }
.wf-help-desk .wf-hd-title { margin: 0 0 18px; font-size: clamp(1.5rem, 3vw, 2rem); }
.wf-hd-grid { display: grid; grid-template-columns: minmax(280px, 340px) minmax(0, 1fr); gap: 16px; align-items: start; }
.wf-hd-list-panel, .wf-hd-detail { min-width: 0; background: var(--hd-surface); border: 1px solid var(--hd-line); border-radius: 8px; }
.wf-hd-controls { display: grid; gap: 12px; padding: 12px; }
.wf-hd-scope { display: flex; gap: 6px; }
.wf-help-desk :where(button, select) { font: inherit; color: inherit; }
.wf-help-desk :where(.wf-hd-list-panel button, .wf-hd-list-panel select, [data-hd-back]) {
    min-height: 44px; padding: 6px 10px; border: 1px solid var(--hd-line); border-radius: 5px; background: var(--hd-surface);
}
.wf-help-desk button:not(:disabled) { cursor: pointer; }
.wf-help-desk :focus-visible { outline: 2px solid var(--hd-focus); outline-offset: 2px; }
.wf-help-desk [aria-pressed="true"], .wf-help-desk .wf-hd-list [aria-current="true"] { background: var(--hd-raised); box-shadow: inset 3px 0 var(--hd-focus); }
.wf-hd-status-label { display: grid; gap: 4px; min-width: 0; color: var(--hd-muted); font-size: .85rem; }
.wf-hd-status-label select { width: 100%; color: var(--hd-text); }
.wf-hd-feedback { color: var(--hd-muted); margin: 0; padding: 0 12px 12px; font-size: .85rem; }
.wf-hd-list { margin: 0; padding: 0; list-style: none; overflow: auto; max-height: min(60vh, 640px); }
.wf-help-desk .wf-hd-list button { display: grid; width: 100%; gap: 4px; text-align: start; padding: 10px 12px; border: 0; border-top: 1px solid var(--hd-line); border-radius: 0; overflow-wrap: anywhere; }
.wf-help-desk .wf-hd-list button:focus-visible { outline-offset: -3px; }
.wf-help-desk .wf-hd-list button:hover { background: var(--hd-raised); }
.wf-hd-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 8px; color: var(--hd-muted); font-size: .78rem; }
.wf-hd-badge { padding: 0 6px; border: 1px solid var(--hd-line); border-radius: 12px; }
.wf-hd-pagination { display: flex; justify-content: space-between; gap: 8px; padding: 12px; }
.wf-hd-detail { min-height: 150px; }
.wf-hd-detail [data-hd-thread] > p { color: var(--hd-muted); padding: 0 16px; }
.wf-help-desk [data-hd-retry], .wf-help-desk [data-hd-back] { margin: 0 12px 12px; }
.wf-help-desk [data-hd-back] { margin-top: 12px; }
.wf-help-desk .elastyc-case-messenger { border: 0; margin: 0; max-width: none; }
@media (max-width: 720px) {
    .wf-hd-grid { grid-template-columns: minmax(0, 1fr); }
    .wf-hd-list { max-height: none; }
    .wf-help-desk:not([data-hd-active]) .wf-hd-detail,
    .wf-help-desk[data-hd-active] .wf-hd-list-panel { display: none; }
}

scripts.content:
(function () {
    'use strict';

    function decode(binding) {
        const bytes = Uint8Array.from(atob(binding.replace(/-/g, '+').replace(/_/g, '/')), value => value.charCodeAt(0));
        return JSON.parse(new TextDecoder().decode(bytes));
    }

    function encode(input) {
        const bytes = new TextEncoder().encode(JSON.stringify(input));
        return btoa(String.fromCharCode(...bytes)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    }

    function text(tag, value, className) {
        const node = document.createElement(tag);
        node.textContent = value;
        if (className) node.className = className;
        return node;
    }

    function init(host) {
        const section = host.querySelector('.wf-help-desk');
        if (!section || section.dataset.hdReady) return;
        section.dataset.hdReady = 'true';

        const scopeButtons = Array.from(section.querySelectorAll('[data-hd-scope]'));
        const select = section.querySelector('[data-hd-status]');
        const feedback = section.querySelector('[data-hd-feedback]');
        const retry = section.querySelector('[data-hd-retry]');
        const list = section.querySelector('[data-hd-list]');
        const pagination = section.querySelector('[data-hd-pagination]');
        const previous = section.querySelector('[data-hd-previous]');
        const next = section.querySelector('[data-hd-next]');
        const back = section.querySelector('[data-hd-back]');
        const thread = section.querySelector('[data-hd-thread]');
        const previewBinding = host.dataset.wfProviderPreview;
        const preview = Boolean(previewBinding || host.hasAttribute('data-wf-provider-preview-error') || window.parent !== window);
        const sample = previewBinding ? decode(previewBinding) : null;
        let scope = 'open';
        let status = '';
        let page = 1;
        let active = null;
        let trigger = null;
        let listRequest;
        let threadRequest;

        async function load(input, signal) {
            const url = new URL(host.dataset.wfProviderUrl, window.location.href);
            url.searchParams.set('wf_input', encode(input));
            const response = await fetch(url, {
                credentials: 'same-origin', cache: 'no-store', referrerPolicy: 'no-referrer', signal
            });
            if (!response.ok) throw new Error(String(response.status));
            const result = await response.json();
            if (!result.ok) throw new Error('Provider response');
            return result.data;
        }

        function paint(data) {
            const options = [new Option('Svi statusi', '')];
            for (const entry of data.statuses) {
                options.push(new Option(entry.label + ' (' + entry.count + ')', entry.label));
            }
            if (status && !data.statuses.some(entry => entry.label === status)) {
                options.push(new Option(status + ' (0)', status));
            }
            select.replaceChildren(...options);
            select.value = status;
            page = data.page;
            pagination.hidden = page === 1 && !data['has-next'];
            previous.disabled = page === 1;
            next.disabled = !data['has-next'];
            feedback.textContent = data.total ? 'Ukupno zahteva: ' + data.total : 'Nema zahteva za izabrane filtere.';
            if (data.fallback) feedback.append(' Prikazani su statusi iz evidencije predmeta.');
            list.replaceChildren(...data.items.map(item => {
                const row = document.createElement('li');
                const button = document.createElement('button');
                button.type = 'button';
                button.dataset.hdNumber = item.number;
                button.setAttribute('aria-current', String(item.number === active));
                const meta = text('span', '', 'wf-hd-meta');
                meta.append(text('span', item.number), text('span', item.status || (item.closed ? 'Zatvoren' : 'Otvoren'), 'wf-hd-badge'));
                if (item.closed && item.status) meta.append(text('span', 'Zatvoren'));
                if (item.activity) {
                    const time = text('time', item.activity.slice(8, 10) + '.' + item.activity.slice(5, 7) + '.' + item.activity.slice(0, 4) + '. ' + item.activity.slice(11, 16));
                    time.dateTime = item.activity.replace(' ', 'T');
                    time.title = 'Poslednja vidljiva aktivnost';
                    meta.append(time);
                }
                button.append(text('strong', item.title), meta);
                button.addEventListener('click', () => open(item.number, button, true));
                row.append(button);
                return row;
            }));
        }

        function previewList() {
            if (!sample) throw new Error('Preview unavailable');
            const rows = sample.items.filter(item => scope === 'all' || !item.closed);
            const counts = new Map();
            rows.forEach(item => counts.set(item.status, (counts.get(item.status) || 0) + 1));
            const items = rows.filter(item => !status || item.status === status);
            return {
                items, total: items.length, page: 1, 'has-next': false,
                statuses: Array.from(counts, ([label, count]) => ({label, count}))
            };
        }

        async function updateList() {
            listRequest?.abort();
            listRequest = new AbortController();
            const {signal} = listRequest;
            if (active) closeThread(false);
            retry.hidden = true;
            pagination.hidden = true;
            list.replaceChildren();
            feedback.textContent = 'Učitavanje zahteva…';
            try {
                const data = preview ? previewList() : await load({scope, status, page}, signal);
                if (!signal.aborted) paint(data);
            } catch (error) {
                if (signal.aborted) return;
                feedback.textContent = 'Zahtevi trenutno nisu dostupni.';
                select.replaceChildren(new Option('Svi statusi', ''), ...(status ? [new Option(status, status)] : []));
                select.value = status;
                retry.hidden = false;
            }
        }

        function closeThread(restoreFocus) {
            threadRequest?.abort();
            active = null;
            delete section.dataset.hdActive;
            back.hidden = true;
            thread.replaceChildren(text('p', 'Izaberite zahtev za pregled razgovora.'));
            list.querySelector('[aria-current="true"]')?.setAttribute('aria-current', 'false');
            if (restoreFocus && trigger?.isConnected) trigger.focus();
        }

        async function open(number, button, addHistory) {
            threadRequest?.abort();
            threadRequest = new AbortController();
            const {signal} = threadRequest;
            active = number;
            trigger = button;
            list.querySelector('[aria-current="true"]')?.setAttribute('aria-current', 'false');
            button?.setAttribute('aria-current', 'true');
            section.dataset.hdActive = 'true';
            back.hidden = false;
            if (addHistory && !preview && window.matchMedia('(max-width: 720px)').matches) {
                history.pushState({wfHelpDesk: host.dataset.wfInstance}, '');
            }
            if (window.matchMedia('(max-width: 720px)').matches) back.focus();
            thread.replaceChildren(text('p', 'Učitavanje razgovora…'));
            try {
                let data;
                if (preview) {
                    const item = sample.items.find(row => row.number === number);
                    data = {thread: {...item, company: 'Primer firme', 'opened-at': item.activity.slice(0, 10), messages: [
                        {id: 1, displayname: 'Podrška', usertype: 'P', datum: '2026-01-12 09:30', text: 'Ovo je primer poruke podrške.'}
                    ]}};
                } else {
                    data = await load({case: number}, signal);
                }
                if (signal.aborted) return;
                if (!window.ElastycCaseMessenger || !data.thread) throw new Error('Conversation unavailable');
                window.ElastycCaseMessenger.mount(thread, {...data.thread, openedAt: data.thread['opened-at']});
            } catch (error) {
                if (signal.aborted) return;
                thread.replaceChildren(text('p', error.message === '404' ? 'Zahtev više nije dostupan.' : 'Razgovor trenutno nije dostupan.'));
            }
        }

        for (const button of scopeButtons) {
            button.addEventListener('click', () => {
                if (scope === button.dataset.hdScope) return;
                scope = button.dataset.hdScope;
                scopeButtons.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
                page = 1;
                updateList();
            });
        }
        select.addEventListener('change', () => { status = select.value; page = 1; updateList(); });
        previous.addEventListener('click', () => { page--; updateList(); });
        next.addEventListener('click', () => { page++; updateList(); });
        retry.addEventListener('click', updateList);
        back.addEventListener('click', () => {
            if (!preview && history.state?.wfHelpDesk === host.dataset.wfInstance) {
                history.back();
            } else {
                closeThread(true);
            }
        });
        if (!preview) {
            window.addEventListener('popstate', () => { if (active) closeThread(true); });
            window.addEventListener('pageshow', event => {
                if (event.persisted) { closeThread(false); updateList(); }
            });
        }
        updateList();
    }

    document.querySelectorAll('[data-wf-component="help-desk"]').forEach(init);
}());
